 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    # The rare nonzero color is the marked motif; the other color(s) form the field.
    color = min((v for v in counts if v != 0), key=lambda v: counts[v])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    minr, maxr = min(r for r,c in pts), max(r for r,c in pts)
    minc, maxc = min(c for r,c in pts), max(c for r,c in pts)
    shape = {(r-minr, c-minc) for r,c in pts}
    out = [row[:] for row in grid]
    for r0 in range(h-(maxr-minr+1)+1):
        for c0 in range(w-(maxc-minc+1)+1):
            cells = [(r0+dr,c0+dc) for dr,dc in shape]
            if all(grid[r][c] == 0 for r,c in cells):
                for r,c in cells:
                    out[r][c] = color
    return out
